export interface EmployeeApiResponse {
  id: string;
  companyId: string;
  userId: string;
  employeeCode: string;
  departmentId: string;
  workLocationId: string | null;
  teamId: string | null;
  managerId: string | null;
  dateOfJoining: string;
  employmentStatus: string;
  role?: string;
  onboardingStep: number;
  profileCompletion: number;
  dateOfLeaving: string | null;
  createdAt: string;
  updatedAt: string;
  user: {
    email: string;
  };
  department: {
    name: string;
  };
  workLocation: {
    name: string;
  } | null;
  team: {
    name: string;
  } | null;
  manager: {
    employeeCode: string;
  } | null;
  personalDetails?: any;
  jobDetails?: any;
  bankDetails?: any;
  statutoryDetails?: any;
  documents?: any[];
}

/** Flattened employee used throughout the frontend UI */
export interface Employee {
  id: string;
  employeeCode: string;
  email: string;
  department: string;
  workLocation: string;
  team: string;
  employmentStatus: string;
  dateOfJoining: string;
  dateOfLeaving: string | null;
  managerId: string | null;
  role?: string;
  onboardingStep: number;
  profileCompletion: number;
  // Raw details for forms
  personalDetails?: any;
  jobDetails?: any;
  bankDetails?: any;
  statutoryDetails?: any;
  documents?: any[];
  departmentId?: string;
  workLocationId?: string;
  teamId?: string;
}

/** Generic API wrapper matching backend response shape */
export interface ApiResponse<T> {
  success: boolean;
  data: T;
}

export interface EmployeeState {
  employees: Employee[];
  loading: boolean;
  error: string | null;
  selectedEmployee: Employee | null;
}

/** Map API response to flat frontend model */
export function mapEmployeeResponse(raw: EmployeeApiResponse): Employee {
  return {
    id: raw.id,
    employeeCode: raw.employeeCode,
    email: raw.user?.email ?? '',
    department: raw.department?.name ?? '',
    workLocation: raw.workLocation?.name ?? '-',
    team: raw.team?.name ?? '-',
    employmentStatus: raw.employmentStatus,
    dateOfJoining: raw.dateOfJoining,
    dateOfLeaving: raw.dateOfLeaving,
    managerId: raw.managerId,
    role: raw.role,
    onboardingStep: raw.onboardingStep,
    profileCompletion: raw.profileCompletion,
    personalDetails: raw.personalDetails,
    jobDetails: raw.jobDetails,
    bankDetails: raw.bankDetails,
    statutoryDetails: raw.statutoryDetails,
    documents: raw.documents || [],
    departmentId: raw.departmentId,
    workLocationId: raw.workLocationId ?? undefined,
    teamId: raw.teamId ?? undefined,
  };
}

export interface EmployeeStats {
    total: number;
    breakdown: { status: string; count: number }[];
}

export interface AttendanceStats {
    presentToday: number;
    overview?: { date: string; present: number; absent: number; late: number }[];
}

export interface ApprovalsPending {
    leaves: number;
    attendance: number;
}

export interface PayrollSummary {
    month: string;
    totalNetSalary: number;
    totalGrossSalary: number;
    employeeCount: number;
}

export interface DashboardSummary {
    employees: EmployeeStats;
    attendance: AttendanceStats;
    approvalsPending: ApprovalsPending;
    latestPayroll: PayrollSummary | null;
}

export interface DashboardState {
    summary: DashboardSummary | null;
    loading: boolean;
    error: string | null;
}

export interface Shift {
    id: string;
    name: string;
    startTime: string; // "HH:mm" stored as Date in DB, returned as ISO string
    endTime: string;   // "HH:mm"
    graceMinutes: number;
    companyId: string;
    createdAt: string;
    updatedAt: string;
}

export type AttendanceStatus = 'present' | 'late' | 'absent' | 'half_day';

export interface AttendanceLog {
    id: string;
    employeeId: string;
    shiftId?: string | null;
    workLocationId?: string | null;
    attendanceDate: string;   // ISO date string — comes as "attendanceDate" from backend
    checkIn: string | null;   // ISO datetime string
    checkOut: string | null;  // ISO datetime string
    totalHours: number | null; // Calculated on checkout
    status: AttendanceStatus;
    note?: string;
    createdAt: string;
    updatedAt: string;
    // Relations included from backend
    employee?: {
        employeeCode: string;
        user: { email: string };
    };
    shift?: {
        name: string;
    };
    workLocation?: {
        name: string;
    };
}

export interface AttendanceState {
    logs: AttendanceLog[];
    totalLogs: number;
    page: number;
    limit: number;
    shifts: Shift[];
    todayStatus: AttendanceLog | null;
    loading: boolean;
    error: string | null;
}

// Flow 2: POST /attendance/check-in
export interface CheckInInput {
    shiftId?: string;        // optional UUID
    workLocationId?: string; // optional UUID
    note?: string;           // optional note
}

// Flow 3: POST /attendance/check-out
export interface CheckOutInput {
    note?: string; // only note is accepted
}

// Flow 1: POST /attendance/shifts
export interface CreateShiftInput {
    name: string;
    startTime: string;     // "HH:mm" format
    endTime: string;       // "HH:mm" format
    graceMinutes?: number; // optional, 0–60
}

// Flow 4: GET /attendance/logs filters
export interface AttendanceLogFilters {
    startDate?: string;  // YYYY-MM-DD
    endDate?: string;    // YYYY-MM-DD
    employeeId?: string; // optional UUID
    status?: AttendanceStatus;
    search?: string;
    page?: number;
    limit?: number;
}

export interface AssignShiftInput {
    employeeId: string;
    shiftId: string;
    effectiveFrom: string; // YYYY-MM-DD
}

export function mapAttendanceLog(raw: any): AttendanceLog {
    return {
        id: raw.id,
        employeeId: raw.employeeId || raw.employee_id,
        shiftId: raw.shiftId || raw.shift_id,
        workLocationId: raw.workLocationId || raw.work_location_id,
        attendanceDate: raw.attendanceDate || raw.attendance_date,
        checkIn: raw.checkIn || raw.check_in,
        checkOut: raw.checkOut || raw.check_out,
        totalHours: raw.totalHours !== undefined ? raw.totalHours : raw.total_hours,
        status: raw.status,
        note: raw.note,
        createdAt: raw.createdAt || raw.created_at,
        updatedAt: raw.updatedAt || raw.updated_at,
        employee: raw.employee,
        shift: raw.shift,
        workLocation: raw.workLocation || raw.work_location,
    };
}

