import { Injectable, signal, computed, inject } from '@angular/core';
import {
    AttendanceLog,
    Shift,
    AttendanceState,
    CheckInInput,
    CheckOutInput,
    CreateShiftInput,
    AttendanceLogFilters,
    AssignShiftInput,
    mapAttendanceLog
} from '../core/models/attendance.model';
import { BaseHttpService } from '../core/services/base-http.service';
import { API_ENDPOINTS } from '../core/constants/app.constants';
import { ApiResponse } from '../core/models/employee.model';
import { NotificationService } from '../core/services/notification.service';
import { finalize } from 'rxjs';

@Injectable({
    providedIn: 'root'
})
export class AttendanceStore {
    private http = inject(BaseHttpService);
    private notify = inject(NotificationService);

    // State
    private state = signal<AttendanceState>({
        logs: [],
        totalLogs: 0,
        page: 1,
        limit: 10,
        shifts: [],
        todayStatus: null,
        loading: false,
        error: null
    });

    // Selectors
    readonly logs = computed(() => this.state().logs);
    readonly totalLogs = computed(() => this.state().totalLogs);
    readonly page = computed(() => this.state().page);
    readonly limit = computed(() => this.state().limit);
    readonly shifts = computed(() => this.state().shifts);
    readonly todayStatus = computed(() => this.state().todayStatus);
    readonly loading = computed(() => this.state().loading);
    readonly error = computed(() => this.state().error);

    // ─── Flow 4: GET /attendance/logs ─────────────────────────────────────────
    loadLogs(filters: AttendanceLogFilters = {}) {
        this.setLoading(true);
        this.state.update(s => ({ ...s, logs: [] })); // Clear previous data
        this.http.get<ApiResponse<{ records: AttendanceLog[], total: number }>>(`${API_ENDPOINTS.ATTENDANCE}/logs`, filters)
            .pipe(finalize(() => this.setLoading(false)))
            .subscribe({
                next: (res) => {
                    const data = res.data as any;
                    const rawRecords = (Array.isArray(data) ? data : data?.records) || [];
                    const records = rawRecords.map(mapAttendanceLog);
                    const total = (Array.isArray(data) ? data.length : data?.total) || 0;

                    this.state.update(s => ({
                        ...s,
                        logs: records,
                        totalLogs: total,
                        page: filters.page ?? s.page,
                        limit: filters.limit ?? s.limit
                    }));

                    // Compare using local date to avoid UTC offset issues (e.g. IST +5:30)
                    const now = new Date();
                    const todayLocal = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
                    const todayLog = records.find((l: AttendanceLog) => {
                        const logDate = l.attendanceDate ? l.attendanceDate.split('T')[0] : '';
                        return logDate === todayLocal;
                    });
                    if (todayLog) {
                        this.state.update(s => ({ ...s, todayStatus: todayLog }));
                    }
                },
                error: (err) => this.handleError('Failed to load attendance logs', err)
            });
    }

    loadAdminLogs(filters: AttendanceLogFilters = {}) {
        this.setLoading(true);
        this.state.update(s => ({ ...s, logs: [] })); // Clear previous data
        this.http.get<ApiResponse<{ records: AttendanceLog[], total: number }>>(`${API_ENDPOINTS.ATTENDANCE_ADMIN_LOGS}`, filters)
            .pipe(finalize(() => this.setLoading(false)))
            .subscribe({
                next: (res) => {
                    const data = res.data as any;
                    const rawRecords = (Array.isArray(data) ? data : data?.records) || [];
                    const records = rawRecords.map(mapAttendanceLog);
                    const total = (Array.isArray(data) ? data.length : data?.total) || 0;

                    this.state.update(s => ({
                        ...s,
                        logs: records,
                        totalLogs: total,
                        page: filters.page ?? s.page,
                        limit: filters.limit ?? s.limit
                    }));
                },
                error: (err) => this.handleError('Failed to load all attendance logs', err)
            });
    }

    // ─── Flow 2: POST /attendance/check-in ────────────────────────────────────
    // Body: { shiftId?, workLocationId?, note? }
    checkIn(data: CheckInInput = {}) {
        this.setLoading(true);
        this.http.post<ApiResponse<AttendanceLog>>(`${API_ENDPOINTS.ATTENDANCE}/check-in`, data)
            .pipe(finalize(() => this.setLoading(false)))
            .subscribe({
                next: (res) => {
                    const mapped = mapAttendanceLog(res.data);
                    const checkInTime = new Date(mapped.checkIn!).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
                    this.state.update(s => ({
                        ...s,
                        todayStatus: mapped,
                        logs: [mapped, ...s.logs]
                    }));
                    this.notify.success('Check-In Successful', `Checked in at ${checkInTime}`);
                },
                error: (err) => this.handleError('Check-In Failed', err)
            });
    }

    // ─── Flow 3: POST /attendance/check-out ───────────────────────────────────
    // Body: { note? } only
    checkOut(data: CheckOutInput = {}) {
        this.setLoading(true);
        this.http.post<ApiResponse<AttendanceLog>>(`${API_ENDPOINTS.ATTENDANCE}/check-out`, data)
            .pipe(finalize(() => this.setLoading(false)))
            .subscribe({
                next: (res) => {
                    const mapped = mapAttendanceLog(res.data);
                    const checkOutTime = new Date(mapped.checkOut!).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
                    this.state.update(s => ({
                        ...s,
                        todayStatus: mapped,
                        logs: s.logs.map(l => l.id === mapped.id ? mapped : l)
                    }));
                    this.notify.success(
                        'Check-Out Successful',
                        `Checked out at ${checkOutTime}. Total: ${mapped.totalHours ?? 0} hrs`
                    );
                },
                error: (err) => this.handleError('Check-Out Failed', err)
            });
    }

    // ─── Flow 1: GET /attendance/shifts ───────────────────────────────────────
    loadShifts() {
        this.setLoading(true);
        this.http.get<ApiResponse<Shift[]>>(`${API_ENDPOINTS.ATTENDANCE}/shifts`)
            .pipe(finalize(() => this.setLoading(false)))
            .subscribe({
