        const presentData = overview.map(d => d.present);
        const absentData = overview.map(d => d.absent);
        const lateData = overview.map(d => d.late);

        return {
            labels,
            datasets: [
                {
                    label: 'Present',
                    backgroundColor: '#10b981',
                    borderColor: '#10b981',
                    data: presentData,
                    borderRadius: 6
                },
                {
                    label: 'Late',
                    backgroundColor: '#f59e0b',
                    borderColor: '#f59e0b',
                    data: lateData,
                    borderRadius: 6
                },
                {
                    label: 'Absent',
                    backgroundColor: '#ef4444',
